#!/usr/bin/env node
"use strict"

/**
 * Seed users exactly as the app's Stripe checkout.session.completed webhook
 * handler (app/api/webhooks/stripe/route.ts) leaves them after a successful
 * subscription checkout:
 *
 *   stripeSubscriptionId: subscription.id
 *   stripeCustomerId:     subscription.customer
 *   stripePriceId:        subscription.items.data[0].price.id
 *   stripeCurrentPeriodEnd: new Date(subscription.current_period_end * 1000)
 *
 * The webhook updates the user by id (session.metadata.userId). Here we upsert
 * by email: existing user -> update those four fields; new user -> create with
 * email + name (name is only set on creation, like a fresh signup).
 *
 * Usage: cd /root/app && node /root/mq/seed.js /root/mq/seed.json
 */

const fs = require("fs")
const path = require("path")

const APP_DIR = "/root/app"

// --- Load DATABASE_URL from /root/app/.env without printing it -------------
function loadEnv(appDir) {
  const envPath = path.join(appDir, ".env")
  if (!fs.existsSync(envPath)) return
  const raw = fs.readFileSync(envPath, "utf8")
  for (const line of raw.split(/\r?\n/)) {
    const m = line.match(/^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)\s*$/)
    if (!m) continue
    const key = m[1]
    let val = m[2].trim()
    if (
      (val.startsWith('"') && val.endsWith('"')) ||
      (val.startsWith("'") && val.endsWith("'"))
    ) {
      val = val.slice(1, -1)
    } else {
      // strip trailing inline comment for unquoted values
      const hash = val.indexOf(" #")
      if (hash !== -1) val = val.slice(0, hash).trim()
    }
    if (process.env[key] === undefined) process.env[key] = val
  }
}

loadEnv(APP_DIR)

if (!process.env.DATABASE_URL) {
  console.error("ERROR: DATABASE_URL not found in /root/app/.env")
  process.exit(1)
}

// --- Load the app's own Prisma client --------------------------------------
const { PrismaClient } = require(path.join(APP_DIR, "node_modules/@prisma/client"))
const db = new PrismaClient()

function toDate(seconds) {
  if (seconds === null || seconds === undefined || seconds === "") return null
  const n = Number(seconds)
  if (!Number.isFinite(n)) throw new Error(`Invalid unix seconds: ${seconds}`)
  return new Date(n * 1000)
}

function clean(v) {
  if (v === undefined || v === null || v === "") return null
  return v
}

async function main() {
  const file = process.argv[2]
  if (!file) {
    console.error("Usage: node /root/mq/seed.js <seed.json>")
    process.exit(1)
  }
  const entries = JSON.parse(fs.readFileSync(file, "utf8"))
  if (!Array.isArray(entries)) throw new Error("Seed file must be a JSON array")

  const results = []
  for (const e of entries) {
    if (!e || !e.email) throw new Error("Every entry needs an email")

    const stripeData = {
      stripeCustomerId: clean(e.stripeCustomerId),
      stripeSubscriptionId: clean(e.stripeSubscriptionId),
      stripePriceId: clean(e.stripePriceId),
      stripeCurrentPeriodEnd: toDate(e.stripeCurrentPeriodEnd),
    }

    const existing = await db.user.findUnique({ where: { email: e.email } })

    let user
    if (existing) {
      // Same fields the webhook writes (update by id).
      user = await db.user.update({
        where: { id: existing.id },
        data: stripeData,
      })
    } else {
      user = await db.user.create({
        data: {
          email: e.email,
          name: clean(e.name),
          ...stripeData,
        },
      })
    }

    results.push({
      action: existing ? "updated" : "created",
      id: user.id,
      email: user.email,
      name: user.name,
      stripeCustomerId: user.stripeCustomerId,
      stripeSubscriptionId: user.stripeSubscriptionId,
      stripePriceId: user.stripePriceId,
      stripeCurrentPeriodEnd: user.stripeCurrentPeriodEnd,
    })
  }

  console.log(JSON.stringify(results, null, 2))
}

main()
  .catch((err) => {
    console.error("SEED FAILED:", err.message)
    process.exitCode = 1
  })
  .finally(async () => {
    await db.$disconnect()
  })

