#!/usr/bin/env node
"use strict"

/**
 * Print a Cookie header value that authenticates as an existing user.
 * Usage: cd /root/app && node /root/mq/session.js <email>
 *
 * Mirrors the app's auth config (lib/auth.ts): NextAuth JWT strategy,
 * PrismaAdapter, jwt callback returns { id, name, email, picture } from the DB.
 * Token is encoded with next-auth/jwt encode() + NEXTAUTH_SECRET from .env,
 * cookie name next-auth.session-token (plain http).
 */

const fs = require("fs")
const path = require("path")

const APP_DIR = "/root/app"

function loadEnv(appDir) {
  const envPath = path.join(appDir, ".env")
  if (!fs.existsSync(envPath)) return
  const raw = fs.readFileSync(envPath, "utf8")
  for (const line of raw.split(/\r?\n/)) {
    const m = line.match(/^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)\s*$/)
    if (!m) continue
    const key = m[1]
    let val = m[2].trim()
    if (
      (val.startsWith('"') && val.endsWith('"')) ||
      (val.startsWith("'") && val.endsWith("'"))
    ) {
      val = val.slice(1, -1)
    } else {
      const hash = val.indexOf(" #")
      if (hash !== -1) val = val.slice(0, hash).trim()
    }
    if (process.env[key] === undefined) process.env[key] = val
  }
}

loadEnv(APP_DIR)

const email = process.argv[2]
if (!email) {
  console.error("Usage: node /root/mq/session.js <email>")
  process.exit(1)
}
if (!process.env.NEXTAUTH_SECRET) {
  console.error("ERROR: NEXTAUTH_SECRET not found in /root/app/.env")
  process.exit(1)
}

const { PrismaClient } = require(path.join(APP_DIR, "node_modules/@prisma/client"))
const { encode } = require(path.join(APP_DIR, "node_modules/next-auth/jwt"))

const db = new PrismaClient()

async function main() {
  const dbUser = await db.user.findUnique({ where: { email } })
  if (!dbUser) {
    console.error(`ERROR: no user with email ${email}`)
    process.exit(1)
  }

  // Same shape the app's jwt callback produces.
  const token = {
    id: dbUser.id,
    name: dbUser.name,
    email: dbUser.email,
    picture: dbUser.image,
  }

  const jwt = await encode({
    token,
    secret: process.env.NEXTAUTH_SECRET,
    maxAge: 30 * 24 * 60 * 60,
  })

  process.stdout.write(`next-auth.session-token=${jwt}\n`)
}

main()
  .catch((err) => {
    console.error("SESSION FAILED:", err.message)
    process.exitCode = 1
  })
  .finally(async () => {
    await db.$disconnect()
  })

